import java.util.*;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long A = sc.nextLong();
        long B = sc.nextLong();
        long C = sc.nextLong();

        if (B <= C) {
            long g = gcd(A, B);
            System.out.println((A / g) + "/" + (B / g));
            return;
        }

        long idx_max = -1;
        String s = "";
        for (long i = 1; i <= C; i++) {
            long j = i * A / B;
            if (Math.abs(i * A - j * B) > Math.abs(i * A - (j + 1) * B))
                j++;
            if (idx_max == -1 || Math.abs(Long.parseLong(s) * A - idx_max * B) * i > Math.abs(i * A - j * B) * Long.parseLong(s)) {
                idx_max = j;
                s = Long.toString(i);
            }
        }
        System.out.println(idx_max + "/" + s);
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
